    Bug 1960372 - Fix bad use of native paths on Windows. r=BenC
    We stopped using the "native" variants of nsIFile methods in bug 1946011, but this one was missed.

    Differential Revision: https://phabricator.services.mozilla.com/D245513

diff --git a/mailnews/local/src/nsLocalUtils.cpp b/mailnews/local/src/nsLocalUtils.cpp
index 872d80faca7..241420e47ff 100644
--- a/mailnews/local/src/nsLocalUtils.cpp
+++ b/mailnews/local/src/nsLocalUtils.cpp
@@ -15,10 +15,6 @@
 #include "nsNetCID.h"
 #include "nsIURIMutator.h"

-#ifdef XP_WIN
-#  include "nsNativeCharsetUtils.h"
-#endif
-
 // it would be really cool to:
 // - cache the last hostname->path match
 // - if no such server exists, behave like an old-style mailbox URL
@@ -119,15 +115,14 @@ nsresult nsLocalURI2Path(const char* rootURI, const char* uriStr,
   rv = server->GetLocalPath(getter_AddRefs(localPath));
   NS_ENSURE_SUCCESS(rv, rv);

-#ifdef XP_WIN
-  nsString path = localPath->NativePath();
-  nsCString localNativePath;
-  NS_CopyUnicodeToNative(path, localNativePath);
-#else
-  nsCString localNativePath = localPath->NativePath();
+  nsAutoString localPathStr;
+  rv = localPath->GetPath(localPathStr);
+  NS_ENSURE_SUCCESS(rv, rv);
+  CopyUTF16toUTF8(localPathStr, pathResult);
+#if defined(XP_WIN)
+  pathResult.Insert('/', 0);
+  pathResult.ReplaceChar('\\', '/');
 #endif
-  nsEscapeNativePath(localNativePath);
-  pathResult = localNativePath.get();
   const char* curPos = uriStr + PL_strlen(rootURI);
   if (curPos) {
     // advance past hostname
@@ -201,10 +196,3 @@ nsresult nsCreateLocalBaseMessageURI(const nsACString& baseURI,

   return NS_OK;
 }
-
-void nsEscapeNativePath(nsCString& nativePath) {
-#if defined(XP_WIN)
-  nativePath.Insert('/', 0);
-  nativePath.ReplaceChar('\\', '/');
-#endif
-}
diff --git a/mailnews/local/src/nsLocalUtils.h b/mailnews/local/src/nsLocalUtils.h
index 0208be84957..0c72ba50bf0 100644
--- a/mailnews/local/src/nsLocalUtils.h
+++ b/mailnews/local/src/nsLocalUtils.h
@@ -24,6 +24,4 @@ nsresult nsBuildLocalMessageURI(const nsACString& baseURI, nsMsgKey key,
 nsresult nsCreateLocalBaseMessageURI(const nsACString& baseURI,
                                      nsCString& baseMessageURI);

-void nsEscapeNativePath(nsCString& nativePath);
-
 #endif  // NS_LOCALUTILS_H
